import 'package:flutter/widgets.dart';
import 'package:flutter_riverpod/flutter_riverpod.dart';

import 'locale_provider.dart';
import '../../l10n/app_localizations.dart';

/// Supplies the app's own translated strings directly for whatever locale
/// is selected — independent of Flutter's built-in Localizations widget
/// resolution, which only works for locales Flutter's Material/Widgets/
/// Cupertino libraries have translations for (Afaan Oromo isn't one of
/// them yet). This means our own app text (via `lookupAppLocalizations`,
/// generated by flutter gen-l10n) is unaffected by that framework gap —
/// only generic Material "chrome" elements (default tooltips, etc.) fall
/// back to English for such locales, which is an acceptable, honest
/// limitation given Flutter itself doesn't support the language yet.
final appL10nProvider = Provider<AppLocalizations>((ref) {
  final locale = ref.watch(localeControllerProvider).valueOrNull ?? const Locale('en');
  return lookupAppLocalizations(locale);
});